import{_ as o,o as a,c as r,a5 as d}from"./chunks/framework.BEZBAInb.js";const h=JSON.parse('{"title":"Logger","description":"","frontmatter":{"title":"Logger","order":4},"headers":[],"relativePath":"ko/latest/tutorial/core/logger.md","filePath":"ko/latest/tutorial/core/logger.md","lastUpdated":1788455378000}'),t={name:"ko/latest/tutorial/core/logger.md"};function c(l,e,n,i,g,s){return a(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="로거-konadologger" tabindex="-1">로거 KonadoLogger <a class="header-anchor" href="#로거-konadologger" aria-label="Permalink to &quot;로거 KonadoLogger&quot;">​</a></h1><h2 id="머리말" tabindex="-1">머리말 <a class="header-anchor" href="#머리말" aria-label="Permalink to &quot;머리말&quot;">​</a></h2><p>KonadoLogger는 Godot Logger 구현을 기반으로 한 로그 모듈입니다. 로그 레벨, 로그 형식, 로그 출력, 로그 파일 등의 기능을 지원하며 Konado 실행 중의 로그 정보를 기록하는 데 사용됩니다.</p><h2 id="로그-경로" tabindex="-1">로그 경로 <a class="header-anchor" href="#로그-경로" aria-label="Permalink to &quot;로그 경로&quot;">​</a></h2><p>로그 파일의 논리 경로는 <code>user://konado_log.log</code>입니다. 실제 디렉터리는 현재 운영 체제와 프로젝트 이름에 따라 Godot가 결정하며 <code>OS.get_user_data_dir()</code>로 확인할 수 있습니다. <code>LOG_FILE_PATH</code>는 기본 상수이므로 경로를 변경하려면 사용자 지정 플러그인 버전에서 이 상수를 관리해야 합니다.</p><h2 id="화면-오버레이-로그" tabindex="-1">화면 오버레이 로그 <a class="header-anchor" href="#화면-오버레이-로그" aria-label="Permalink to &quot;화면 오버레이 로그&quot;">​</a></h2><p>오류가 발생하면 대화 장면은 화면 위에 로그 창을 덮어 표시하여 오류 정보를 보여 주고 게임 실행을 중단합니다. 일반 경고는 계속 로그 파일에 기록되지만 런타임 오류로 표시되거나 게임을 중단하지는 않습니다. 오류 오버레이를 끄려면 <code>KonadoDialogueManager</code>의 <code>enable_overlay_log</code> 속성을 <code>false</code>로 설정하세요.</p><h2 id="로그-콜백" tabindex="-1">로그 콜백 <a class="header-anchor" href="#로그-콜백" aria-label="Permalink to &quot;로그 콜백&quot;">​</a></h2><p><code>KonadoLogger</code> 인스턴스는 <code>error_caught(msg)</code>와 <code>message_caught(message, error)</code> 신호를 보냅니다. <code>KonadoDialogueManager</code>는 씬 트리에 들어갈 때 내부 로거를 만들어 Godot에 등록하고 <code>error_caught</code>로 화면 오버레이를 구동합니다. 로거는 전역 자동 로드 객체가 아닙니다. 별도의 <code>KonadoLogger</code>를 만드는 사용자 지정 연동은 <code>OS.add_logger()</code>로 등록하고 해제 전에 <code>OS.remove_logger()</code>를 호출하여 중복 기록이나 유효하지 않은 인스턴스가 남지 않게 해야 합니다.</p><h2 id="런타임-실패" tabindex="-1">런타임 실패 <a class="header-anchor" href="#런타임-실패" aria-label="Permalink to &quot;런타임 실패&quot;">​</a></h2><p>원자 명령 실행이 실패하면 <code>KonadoDialogueManager</code>는 최종 오류 한 건만 기록하고 <code>runtime_failure_reported(failure)</code> 신호를 보냅니다. <code>failure</code>에는 안정적인 오류 코드, 작업, 관련 리소스, 근본 원인, 소스 경로와 줄, 명령 ID, opcode, 프로그램 위치가 포함되어 오류 보고나 사용자 지정 디버깅 UI에 사용할 수 있습니다. 간단한 인터페이스인 <code>runtime_failed(message, instruction_id, source_line)</code>도 계속 제공됩니다.</p>',11)])])}const u=o(t,[["render",c]]);export{h as __pageData,u as default};
